#!/usr/bin/env bash
input=$(cat)

# Source theme colors (generated by tinty's apply-extras.rb)
SL_COLORS="$HOME/.claude/statusline-colors.env"
[ -f "$SL_COLORS" ] && source "$SL_COLORS"

vim_mode=$(echo "$input" | jq -r '.vim.mode // empty')
session_name=$(echo "$input" | jq -r '.session_name // empty')
model=$(echo "$input" | jq -r '.model.display_name // empty')
thinking=$(echo "$input" | jq -r '.thinking.enabled // empty')
worktree_branch=$(echo "$input" | jq -r '.worktree.branch // empty')
pr_number=$(echo "$input" | jq -r '.pr.number // empty')
pr_state=$(echo "$input" | jq -r '.pr.review_state // empty')
remaining=$(echo "$input" | jq -r '.context_window.remaining_percentage // empty')
effort=$(echo "$input" | jq -r '.effort.level // empty')

# Separator (U+25E2 black lower right triangle)
arrow=$(printf "\xe2\x97\xa2")

# prev_bg tracks the last field's background color for arrow transitions
prev_bg=""

# Emit a powerline segment: pill <fg> <bg> <text>
pill() {
  local fg="$1" bg="$2" text="$3"
  if [ -n "$prev_bg" ]; then
    printf "\033[%s;%sm%s" "$prev_bg" "${bg/48;/38;}" "$arrow"
  fi
  printf "\033[%s;%sm %s\033[0m" "$fg" "$bg" "$text"
  prev_bg="${bg}"
}

# Close the last segment (U+25E4 black upper left triangle)
close() {
  if [ -n "$prev_bg" ]; then
    close_arrow=$(printf "\xe2\x97\xa4")
    printf "\033[%sm%s\033[0m" "${prev_bg/48;/38;}" "$close_arrow"
  fi
}

# Vim mode
if [ -n "$vim_mode" ]; then
  case "$vim_mode" in
    NORMAL) pill "${FG_VIM_NOR:-38;5;0}" "${BG_VIM_NOR:-48;5;34}" "NOR" ;;
    INSERT) pill "${FG_VIM_INS:-38;5;0}" "${BG_VIM_INS:-48;5;214}" "INS" ;;
    VISUAL*) pill "${FG_VIM_VIS:-38;5;0}" "${BG_VIM_VIS:-48;5;134}" "VIS" ;;
  esac
fi

# Session name
if [ -n "$session_name" ]; then
  pill "${FG_SESSION:-38;5;255}" "${BG_SESSION:-48;5;90}" "$session_name"
fi

# Model name
if [ -n "$model" ]; then
  pill "${FG_MODEL:-38;5;255}" "${BG_MODEL:-48;5;25}" "$model"
fi

# Thinking
if [ "$thinking" = "true" ]; then
  pill "${FG_THINK:-38;5;0}" "${BG_THINK:-48;5;37}" "think"
else
  pill "${FG_NOTHINK:-38;5;245}" "${BG_NOTHINK:-48;5;236}" "no-think"
fi

# Effort level
if [ -n "$effort" ]; then
  pill "${FG_EFFORT:-38;5;255}" "${BG_EFFORT:-48;5;240}" "$effort"
fi

# Context remaining
if [ -n "$remaining" ]; then
  pct=$(printf "%.0f" "$remaining")
  dot_count=8
  filled=$(( pct * dot_count / 100 ))
  empty=$(( dot_count - filled ))
  if [ "$pct" -lt 20 ]; then
    bg="${BG_CTX_LOW:-48;5;124}"
  elif [ "$pct" -lt 50 ]; then
    bg="${BG_CTX_MED:-48;5;136}"
  else
    bg="${BG_CTX_HIGH:-48;5;22}"
  fi
  dots=""
  for ((i=0; i<filled; i++)); do dots+="●"; done
  for ((i=0; i<empty; i++)); do dots+="○"; done
  pill "${FG_CTX:-38;5;0}" "$bg" "${dots}${pct}%"
fi

# Worktree branch
if [ -n "$worktree_branch" ]; then
  pill "${FG_WORKTREE:-38;5;0}" "${BG_WORKTREE:-48;5;34}" " $worktree_branch"
fi

# PR info
if [ -n "$pr_number" ]; then
  state_icon=""
  case "$pr_state" in
    approved) state_icon=" ✓" ;;
    changes_requested) state_icon=" ✗" ;;
    draft) state_icon=" draft" ;;
    pending) state_icon=" …" ;;
  esac
  pill "${FG_PR:-38;5;255}" "${BG_PR:-48;5;30}" "#${pr_number}${state_icon}"
fi

close
